// Issue 93: ROMAN (NCT03689712, GTI-4419-301), the avasopasem manganese phase 3 in radiation-induced severe oral mucositis.
// Status "mixed": the primary endpoint met its statistical test, but the paper itself records that the FDA did not find the
// benefit-risk sufficient for approval and asked for a confirmatory trial.
const issue93: (TrialInput | PaperInput)[] = [
  t({ id: "roman", name: "ROMAN", aka: ["GTI-4419-301", "Reduction in Oral Mucositis With Avasopasem Manganese"], nct: "NCT03689712", phase: "3", status: "mixed", yearReported: 2025, sponsor: "Galera Therapeutics", enrolled: 455,
    setting: "Locally advanced, non-metastatic head and neck cancer receiving intensity-modulated radiotherapy plus cisplatin: avasopasem manganese 90 mg versus placebo infused before each radiotherapy fraction, randomised 3:2",
    tldr: "ROMAN showed that an infusion of avasopasem before each dose of radiotherapy cut severe mouth ulcers during head and neck chemoradiation from about two thirds of patients to about half and shortened them from 18 days to 8, but the effect was smaller than an earlier trial had promised and the FDA asked for another study before approval.",
    summary: "ROMAN (NCT03689712; organisation id GTI-4419-301) was a double-blind, placebo-controlled phase 3 trial of avasopasem manganese (GC4419), a superoxide dismutase mimetic, in patients with locally advanced head and neck cancer receiving 60 to 72 Gy of intensity-modulated radiotherapy (more than 50 Gy to at least two oral mucosal sites) with cisplatin every three weeks or weekly. Patients were randomised 3:2 to avasopasem 90 mg or placebo before each radiotherapy fraction. Severe oral mucositis (WHO grade 3 or 4) was assessed twice weekly during radiotherapy and weekly for two weeks after; the primary endpoint was its cumulative incidence through the end of radiotherapy.\n\nOf 455 patients randomised, 407 (241 avasopasem, 166 placebo) formed the primary analysis population. Severe oral mucositis occurred in 54 percent on avasopasem versus 64 percent on placebo (relative risk 0.84; 95 percent CI 0.71 to 1.00; p = 0.045), and its median duration was 8 versus 18 days (p = 0.002); onset was nominally delayed (median 49 versus 38 days). Grade 4 mucositis incidence and duration were not significantly reduced (27 percent, p = 0.052; 24 percent, p = 0.143). Adverse-event frequencies were comparable, tumour outcomes were maintained at one year, and two-year overall survival was 89 percent (95 percent CI 84 to 93) with avasopasem versus 93 percent (88 to 96) with placebo.\n\nThe eClinicalMedicine 2025 report states that the incidence benefit was smaller than the phase 2b trial had predicted, that a contribution of avasopasem to adverse events could not be excluded, and that ROMAN did not give a sufficiently favourable benefit-risk determination for FDA approval; a confirmatory phase 3 was requested. The FDA issued a complete response letter in August 2023, and the drug remains investigational. The registry condition is oral mucositis rather than a cancer, which is why the automated pass never attached the trial to the drug.",
    result: "Severe oral mucositis incidence 54% vs 64% (relative risk 0.84, 95% CI 0.71 to 1.00; p = 0.045); median duration 8 vs 18 days (p = 0.002). Primary met, but the FDA issued a complete response letter and asked for a confirmatory trial.",
    outcomes: [
      { endpoint: "Severe oral mucositis (WHO grade 3 or 4) incidence through the end of radiotherapy", primary: true, unit: "%", arms: [{ name: "Avasopasem manganese 90 mg", n: 241, value: 54, note: "Relative risk 0.84 vs placebo; 95% CI 0.71 to 1.00" }, { name: "Placebo", n: 166, value: 64 }], p: "0.045", source: "https://doi.org/10.1016/j.eclinm.2025.103539" },
      { endpoint: "Median duration of severe oral mucositis", unit: "days", arms: [{ name: "Avasopasem manganese 90 mg", n: 241, value: 8 }, { name: "Placebo", n: 166, value: 18 }], p: "0.002", source: "https://doi.org/10.1016/j.eclinm.2025.103539" },
      { endpoint: "Median time to onset of severe oral mucositis", unit: "days", arms: [{ name: "Avasopasem manganese 90 mg", n: 241, value: 49, note: "Nominal p = 0.002" }, { name: "Placebo", n: 166, value: 38 }], source: "https://doi.org/10.1016/j.eclinm.2025.103539" },
      { endpoint: "Overall survival at 2 years", unit: "%", arms: [{ name: "Avasopasem manganese 90 mg", value: 89, note: "95% CI 84 to 93; tumour outcomes were maintained at one year" }, { name: "Placebo", value: 93, note: "95% CI 88 to 96" }], source: "https://doi.org/10.1016/j.eclinm.2025.103539" },
    ],
    replication: "The randomised phase 2b (Anderson, JCO 2020; NCT02508389) had reported a larger effect on the same endpoints; ROMAN confirmed the direction but not the size, and the confirmatory phase 3 the FDA requested has not reported.",
    drugs: ["avasopasem-manganese", "cisplatin"], cancers: ["head-and-neck"], technologies: ["radioprotectors"], companies: ["galera-therapeutics"], keyPapers: ["paper-roman-anderson-eclinicalmedicine-2025"],
    links: [ct("NCT03689712"), doi("eClinicalMedicine 2025", "10.1016/j.eclinm.2025.103539")] }),
  p({ id: "paper-roman-anderson-eclinicalmedicine-2025", name: "Avasopasem manganese treatment for severe oral mucositis from chemoradiotherapy for locally advanced head and neck cancer: phase 3 randomized controlled trial (ROMAN)",
    tldr: "Giving avasopasem before each radiotherapy session lowered the share of head and neck cancer patients who got severe mouth ulcers from 64 to 54 percent and cut how long the ulcers lasted from 18 days to 8, but the gain was smaller than hoped and the FDA wanted another trial.",
    summary: "Primary publication of ROMAN (NCT03689712). Patients receiving 60 to 72 Gy of intensity-modulated radiotherapy (more than 50 Gy to at least two oral mucosal sites) plus cisplatin for locally advanced head and neck cancer were randomised 3:2 to avasopasem manganese 90 mg or placebo before each radiotherapy fraction. Severe oral mucositis (WHO grade 3 or 4) was assessed twice weekly during radiotherapy and weekly for two weeks after. The primary endpoint was the incidence of severe oral mucositis through the end of radiotherapy; secondary endpoints included its duration and onset, grade 4 incidence and duration, tumour outcomes and renal function.\n\n455 patients were randomised and 407 (241 avasopasem, 166 placebo) entered the primary analysis. Severe oral mucositis incidence was 54 percent versus 64 percent (relative risk 0.84; 95 percent CI 0.71 to 1.00; p = 0.045) and median duration 8 versus 18 days (p = 0.002); onset was nominally delayed (median 49 versus 38 days). Grade 4 incidence (27 percent, p = 0.052) and days (24 percent, p = 0.143) were not significantly reduced. Adverse-event frequencies were comparable; tumour outcomes were maintained at one year, and two-year overall survival was 89 percent (84 to 93) with avasopasem versus 93 percent (88 to 96) with placebo. The authors write that the incidence benefit was smaller than the phase 2b had predicted, that avasopasem's contribution to adverse events could not be excluded, and that ROMAN did not provide a sufficiently favourable benefit-risk determination for FDA approval; a confirmatory phase 3 trial was requested.",
    journal: "eClinicalMedicine", year: 2025, doi: "10.1016/j.eclinm.2025.103539", pmid: "41127563",
    authors: "Anderson C, Lee CM, Kelley JR, et al.", paperType: "rct", participants: 455, changedPractice: false,
    findings: ["Severe oral mucositis incidence 54 percent with avasopasem vs 64 percent with placebo (relative risk 0.84; 95 percent CI 0.71 to 1.00; p = 0.045).", "Median duration of severe oral mucositis 8 vs 18 days (p = 0.002); onset delayed to a median of 49 vs 38 days.", "Grade 4 mucositis not significantly reduced; two-year overall survival 89 percent vs 93 percent."],
    whatItMeans: "Severe mouth ulcers are the most disabling acute effect of head and neck chemoradiation and there is still no approved drug to prevent them. ROMAN shows that a radioprotector can reduce them, but by less than the phase 2b suggested, and the upper confidence limit of 1.00 plus the numerically lower two-year survival left the FDA unconvinced. The product stays investigational until a confirmatory trial reports.",
    caveats: ["The confidence interval for the primary relative risk reaches 1.00, and the p value is 0.045.", "Two-year overall survival was numerically lower on avasopasem (89 percent vs 93 percent); the confidence intervals overlap, but the authors say a contribution to adverse events could not be excluded.", "The primary analysis population (407) is smaller than the randomised population (455).", "Funded by Galera Therapeutics; published two years after the FDA complete response letter."],
    links: [doi("eClinicalMedicine 2025", "10.1016/j.eclinm.2025.103539"), pubmed("41127563"), ct("NCT03689712")],
    drugs: ["avasopasem-manganese"], trials: ["roman"], cancers: ["head-and-neck"], technologies: ["radioprotectors"], companies: ["galera-therapeutics"] }),
];

// Issue 94: PSMA-PreRP, the UCLA and UCSF 68Ga-PSMA-11 PET staging programme (NCT03368547, NCT02919111, NCT02611882) that the
// Illuccix label names Study 1 and that founded the gallium-68 gozetotide New Drug Application. Registry phase for NCT03368547 is NA;
// the paper calls itself a phase 3 imaging trial, and the roadmap watch treats an empty registry phase as no contradiction.
const issue94: (TrialInput | PaperInput)[] = [
  t({ id: "psma-prerp", name: "PSMA-PreRP", aka: ["68Ga-PSMA-11 PET before radical prostatectomy", "16-001684"], nct: "NCT03368547", phase: "3", status: "positive", yearReported: 2021, sponsor: "UCLA Jonsson Comprehensive Cancer Center and UCSF (investigator initiated)",
    enrolled: 764, enrolledBasis: "registered", enrolledNote: "The JAMA Oncology 2021 report covers 764 men imaged under three registrations (NCT03368547, NCT02919111 and NCT02611882), of whom 277 had surgery and formed the efficacy cohort; ClinicalTrials.gov NCT03368547 alone lists an actual enrolment of 400.",
    setting: "Intermediate- to high-risk prostate cancer considered for radical prostatectomy: a single 68Ga-PSMA-11 PET scan for pelvic nodal staging, read against histopathology after prostatectomy and pelvic lymph node dissection",
    tldr: "The UCLA and UCSF scan study behind the first US approval of gallium PSMA PET: in men heading for prostate surgery it was very reliable when it called a pelvic lymph node positive, but it still missed about three in five of the nodes that pathology later found.",
    summary: "PSMA-PreRP is the US Illuccix label's name (Study 1) for the investigator-initiated, prospective, multicentre, single-arm, open-label phase 3 diagnostic-efficacy programme of 68Ga-PSMA-11 PET before planned radical prostatectomy at the University of California, San Francisco and the University of California, Los Angeles (Hope and colleagues, JAMA Oncology 2021; ClinicalTrials.gov NCT03368547, NCT02611882 and NCT02919111). From December 2015 to December 2019, men with intermediate- to high-risk prostate cancer had one PET scan with 3 to 7 mCi of 68Ga-PSMA-11. Each scan was read centrally by three blinded readers with a majority rule, and pelvic nodal findings were compared with histopathology after prostatectomy and pelvic lymph node dissection using nodal-region correlation.\n\nOf 764 men imaged, 277 (36 percent) went on to prostatectomy with lymph node dissection and formed the efficacy cohort; 75 of them (27 percent) had pelvic nodal metastasis on pathology. PET was positive for pelvic nodal, extrapelvic nodal and bone disease in 14, 1 and 3 percent. Per-patient sensitivity for pelvic nodal metastasis was 0.40 (95 percent CI 0.34 to 0.46), specificity 0.95 (0.92 to 0.97), positive predictive value 0.75 (0.70 to 0.80) and negative predictive value 0.81 (0.76 to 0.85). Of the 487 men who did not have surgery, most had radiotherapy (69 percent of those with follow-up) or systemic therapy (22 percent).\n\nThe authors state that the collaboration formed the foundation of the New Drug Application for 68Ga-PSMA-11, approved in December 2020. Telix's Illuccix kit (FDA December 2021) cites the programme as Study 1 (NCT03368547 and NCT02919111) and states that its efficacy for initial staging rests on that study of another gozetotide formulation; the label's own summary reports a 325-patient two-centre cut with 123 evaluable, which is a different analysis set from the paper's and is not used for the outcome rows here.",
    result: "Per-patient sensitivity 0.40 (95% CI 0.34 to 0.46) and specificity 0.95 (0.92 to 0.97) for pelvic nodal metastasis against histopathology in the 277-man surgery cohort; positive predictive value 0.75, negative predictive value 0.81.",
    outcomes: [
      { endpoint: "Sensitivity for pelvic nodal metastasis (per patient, nodal-region correlation, versus histopathology)", primary: true, unit: "%", arms: [{ name: "68Ga-PSMA-11 PET", n: 277, value: 40, note: "Reported as 0.40; 95% CI 0.34 to 0.46; 75 of 277 men had nodal metastasis on pathology" }], source: "https://doi.org/10.1001/jamaoncol.2021.3771" },
      { endpoint: "Specificity for pelvic nodal metastasis (per patient, nodal-region correlation, versus histopathology)", primary: true, unit: "%", arms: [{ name: "68Ga-PSMA-11 PET", n: 277, value: 95, note: "Reported as 0.95; 95% CI 0.92 to 0.97" }], source: "https://doi.org/10.1001/jamaoncol.2021.3771" },
      { endpoint: "Positive predictive value for pelvic nodal metastasis", unit: "%", arms: [{ name: "68Ga-PSMA-11 PET", n: 277, value: 75, note: "Reported as 0.75; 95% CI 0.70 to 0.80" }], source: "https://doi.org/10.1001/jamaoncol.2021.3771" },
      { endpoint: "Negative predictive value for pelvic nodal metastasis", unit: "%", arms: [{ name: "68Ga-PSMA-11 PET", n: 277, value: 81, note: "Reported as 0.81; 95% CI 0.76 to 0.85" }], source: "https://doi.org/10.1001/jamaoncol.2021.3771" },
    ],
    replication: "proPSMA (Hofman, Lancet 2020; recorded as propsma) randomised PSMA PET/CT against conventional imaging for staging high-risk disease in Australia and found higher accuracy; OSPREY and CONDOR did the same job for the fluorine-18 tracer piflufolastat (Pylarify).",
    drugs: ["illuccix", "ga68-psma-11"], cancers: ["prostate", "prostate-high-risk"], targets: ["psma"], technologies: ["psma-pet", "pet-ct"], institutions: ["ucla-jonsson", "ucsf"], people: ["thomas-hope"], terms: ["sensitivity-specificity", "ppv"], keyPapers: ["paper-psma-prerp-hope-jama-oncol-2021"],
    links: [ct("NCT03368547"), ct("NCT02919111"), ct("NCT02611882"), doi("JAMA Oncology 2021", "10.1001/jamaoncol.2021.3771"), { label: "Illuccix label (DailyMed)", url: "https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d4643b31-9b4f-673f-e053-2a95a90a559d" }] }),
  p({ id: "paper-psma-prerp-hope-jama-oncol-2021", name: "Diagnostic accuracy of 68Ga-PSMA-11 PET for pelvic nodal metastasis detection prior to radical prostatectomy and pelvic lymph node dissection: a multicenter prospective phase 3 imaging trial",
    tldr: "In 277 men whose prostate and pelvic lymph nodes were removed after a gallium PSMA scan, the scan correctly flagged 40 percent of the men with cancer in their nodes and was right 95 percent of the time when it called the nodes clear.",
    summary: "Report of the investigator-initiated, prospective, multicentre, single-arm, open-label phase 3 imaging trial of 68Ga-PSMA-11 PET at UCSF and UCLA (NCT03368547, NCT02611882 and NCT02919111), which enrolled 764 men with intermediate- to high-risk prostate cancer considered for prostatectomy between December 2015 and December 2019. Each man had one PET scan with 3 to 7 mCi of 68Ga-PSMA-11, read by three blinded central readers with a majority rule. The primary endpoint was per-patient sensitivity and specificity for pelvic lymph node metastasis against histopathology, with nodal-region correlation.\n\nOf the 764 men, 277 (36 percent) underwent prostatectomy with lymph node dissection and formed the efficacy cohort; 75 (27 percent) had pelvic nodal metastasis on pathology. PET was positive in 40 (14 percent), 2 (1 percent) and 7 (3 percent) of the 277 for pelvic nodal, extrapelvic nodal and bone disease. Sensitivity, specificity, positive predictive value and negative predictive value for pelvic nodal metastasis were 0.40 (95 percent CI 0.34 to 0.46), 0.95 (0.92 to 0.97), 0.75 (0.70 to 0.80) and 0.81 (0.76 to 0.85). Of the 487 men who did not have surgery, 108 were lost to follow-up; the rest mostly had radiotherapy (69 percent) or systemic therapy (22 percent). The authors describe the collaboration as the largest of its kind and the foundation of the New Drug Application for 68Ga-PSMA-11.",
    journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2021.3771", pmid: "34529005",
    authors: "Hope TA, Eiber M, Armstrong WR, et al.", paperType: "observational", participants: 764, changedPractice: true,
    findings: ["Per-patient sensitivity 0.40 (95 percent CI 0.34 to 0.46) and specificity 0.95 (0.92 to 0.97) for pelvic nodal metastasis against histopathology in 277 men.", "Positive predictive value 0.75 and negative predictive value 0.81; 27 percent of the surgery cohort had nodal metastasis.", "764 men imaged; 36 percent went on to prostatectomy with lymph node dissection."],
    whatItMeans: "This academic programme is what the FDA approved 68Ga-PSMA-11 on in December 2020, and the Illuccix and Locametz kits rest on it for the staging indication. Its message for a man being staged before surgery is that a positive PSMA PET node is very likely real, but a negative scan does not rule out small nodal deposits, so the lymph node dissection still matters.",
    caveats: ["Only 36 percent of imaged men reached the surgical reference standard, so the efficacy cohort is a selected subset.", "Sensitivity of 0.40 means most nodal metastases found at surgery were missed, largely because they were small.", "Single-arm accuracy study; the randomised comparison with conventional imaging is proPSMA."],
    links: [doi("JAMA Oncology 2021", "10.1001/jamaoncol.2021.3771"), pubmed("34529005"), ct("NCT03368547")],
    drugs: ["ga68-psma-11", "illuccix"], trials: ["psma-prerp"], cancers: ["prostate", "prostate-high-risk"], targets: ["psma"], technologies: ["psma-pet"], institutions: ["ucla-jonsson", "ucsf"], people: ["thomas-hope"], journals: ["jama-oncology"] }),
];

